Obracíme pouze porovnání počtu tanců, teprve potom přidáme vzestupné jméno. Reversed na konci celého řetězce by otočilo i druhé pravidlo. Nový ArrayList chrání původní pořadí.

**Main.java**

```java
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

public class Main {
    record Guest(String name, int dances) {}

    static List<Guest> ordered(List<Guest> original) {
        List<Guest> result = new ArrayList<>(original);
        result.sort(Comparator.comparingInt(Guest::dances).reversed()
                .thenComparing(Guest::name));
        return result;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int count = Integer.parseInt(input.nextLine());
        List<Guest> guests = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            String[] parts = input.nextLine().split(";", -1);
            guests.add(new Guest(parts[0], Integer.parseInt(parts[1])));
        }
        for (Guest guest : ordered(guests)) System.out.println(guest.name() + ": " + guest.dances());
        System.out.println("Puvodni prvni: " + (guests.isEmpty() ? "-" : guests.get(0).name()));
    }
}
```
